curated.blandas.intermedio=intermediateSituations.map((r,i)=>[...topicMap[i],`Caso: ${r[0]} ¿Cuál es la mejor respuesta?`,...r.slice(1),`La opción correcta aplica ${topicMap[i][1].toLowerCase()} mediante análisis responsable y respeto. ${r[1]}: es la respuesta constructiva; las otras alternativas omiten evidencia, cuidado o responsabilidad.`]);
curated.blandas.avanzado=advancedSituations.map((r,i)=>[...topicMap[i],`Analiza el caso: ${r[0]} ¿Qué decisión está mejor justificada?`,...r.slice(1),`En un contexto complejo, ${r[1].charAt(0).toLowerCase()+r[1].slice(1)} aporta una solución razonada y ética. Los distractores introducen sesgos, daño o falta de transparencia.`]);